import type { Difficulty, Syllabus, Topic } from "../types";
import { unpack } from "./codec";
import { pick, shuffle } from "./utils";

type Item = [prompt: string, answer: string, distractors: string[], explanation: string];

const ANIMALS: Item[] = unpack("");
const OUR_WORLD: Item[] = unpack("");
const BODY: Item[] = unpack("");
const SPACE: Item[] = unpack("");
const RIDDLES: Item[] = unpack("");
const ANCIENT: Item[] = unpack("");
const AUS_HISTORY: Item[] = unpack("");
const GEOGRAPHY: Item[] = unpack("");
const SCIENCE: Item[] = unpack("");
const INVENTORS: Item[] = unpack("");
const TRUE_FALSE: Item[] = unpack("");
const MODERN: Item[] = unpack("");
const CIVICS: Item[] = unpack("");
const CURRENT: Item[] = unpack("");
const WORLD_GEO: Item[] = unpack("");
const ARTS: Item[] = unpack("");
const BRAIN: Item[] = unpack("");
const IDEAS: Item[] = unpack("");
const SCI_HISTORY: Item[] = unpack("");

function quiz(id: string, label: string, items: Item[]): Topic {
  return {
    id,
    label,
    generate: () => {
      const [prompt, answer, distractors, explanation] = pick(items);
      return { prompt, answer, options: shuffle([answer, ...distractors]), explanation };
    },
  };
}

const animals = () => quiz("gk-animals", "Animals and nature", ANIMALS);
const ourWorld = () => quiz("gk-our-world", "Our world", OUR_WORLD);
const body = () => quiz("gk-body", "Body and health", BODY);
const space = () => quiz("gk-space-weather", "Space and weather", SPACE);
const riddles = () => quiz("gk-fun-riddles", "Fun quiz: riddles and odd one out", RIDDLES);

const ancient = () => quiz("gk-world-history", "World history", ANCIENT);
const ausHistory = () => quiz("gk-aus-history", "Australian history", AUS_HISTORY);
const geography = () => quiz("gk-geography", "Geography", GEOGRAPHY);
const science = () => quiz("gk-science-facts", "Science facts", SCIENCE);
const inventors = () => quiz("gk-inventors", "Inventors and discoveries", INVENTORS);
const trueFalse = () => quiz("gk-fun-true-false", "Fun quiz: true or false", TRUE_FALSE);

const modern = () => quiz("gk-modern-history", "Modern world history", MODERN);
const civics = () => quiz("gk-civics", "Government and civics", CIVICS);
const current = () => quiz("gk-current", "Current topics (evergreen)", CURRENT);
const worldGeo = () => quiz("gk-world-geography", "World geography", WORLD_GEO);
const arts = () => quiz("gk-arts", "Arts, books and culture", ARTS);
const brain = () => quiz("gk-fun-brain", "Fun quiz: brain teasers", BRAIN);

const ideas = () => quiz("gk-ideas", "Political ideas and thinkers", IDEAS);
const sciHistory = () => quiz("gk-science-history", "Great scientists and discoveries", SCI_HISTORY);

function baseGeneralTopics(grade: number): Topic[] {
  if (grade <= 4) return [animals(), ourWorld(), body(), space(), riddles()];
  if (grade <= 8) return [ancient(), ausHistory(), geography(), science(), inventors(), trueFalse()];
  return [modern(), civics(), current(), worldGeo(), arts(), brain()];
}

/** "Advanced" pulls in the next band's topics; the top band gets new extension topics. */
function advancedGeneralExtras(grade: number): Topic[] {
  if (grade <= 4) return [geography(), trueFalse()];
  if (grade <= 8) return [modern(), civics()];
  return [ideas(), sciHistory()];
}

export function getGeneralTopics(
  grade: number,
  _syllabus: Syllabus = "vic",
  difficulty: Difficulty = "standard",
): Topic[] {
  return [...baseGeneralTopics(grade), ...(difficulty === "advanced" ? advancedGeneralExtras(grade) : [])];
}
